<script setup lang="ts">
import { reactive } from 'vue';
import { router } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import { CheckCircle2, Clock3, UserRound, XCircle } from '@lucide/vue';
import AppLayout from '../../Layouts/AppLayout.vue';
defineOptions({ layout: AppLayout });
const props = defineProps<{ users: { data: Array<any>; current_page: number; last_page: number; from: number; to: number; total: number }; roles: string[] }>();
const roleLabels: Record<string, string> = { super_admin: 'Super Admin', admin: 'Admin', inspector: 'Inspector/QA', user: 'User' };
const roleSel = reactive<Record<number, string>>({});
props.users.data.forEach((u) => { roleSel[u.id] = (u.requested_role ?? u.roles?.[0]?.name) ?? 'user'; });
const approve = (u: any) => router.post(route('users.approve', { user: u.id }), { role: roleSel[u.id] }, { preserveScroll: true });
const changeRole = (u: any) => router.post(route('users.role', { user: u.id }), { role: roleSel[u.id] }, { preserveScroll: true });
const deactivate = (u: any) => { if (window.confirm(`Nonaktifkan "${u.name}"?`)) router.post(route('users.deactivate', { user: u.id }), {}, { preserveScroll: true }); };
const pendingUsers = props.users.data.filter((u) => !u.is_approved); const activeUsers = props.users.data.filter((u) => u.is_approved);
</script>
<template><div class="mx-auto max-w-5xl space-y-8"><section><div class="mb-3 flex items-center gap-2"><Clock3 :size="18" class="text-amber-500" /><h2 class="text-sm font-bold">Menunggu Persetujuan ({{ pendingUsers.length }})</h2></div><div v-if="pendingUsers.length === 0" class="rounded-xl border border-dashed border-slate-300 bg-white p-8 text-center text-sm text-slate-500">Tidak ada user menunggu persetujuan.</div><div v-else class="space-y-3"><div v-for="u in pendingUsers" :key="u.id" class="user-card pending"><div class="flex min-w-0 items-start gap-3"><UserRound :size="19" class="mt-1 text-amber-600" /><div><div class="font-bold">{{ u.name }}</div><div class="text-xs text-slate-500">{{ u.email }} · NIK: {{ u.nik }}</div><span class="mt-2 inline-flex rounded-full bg-amber-100 px-2 py-1 text-[10px] font-bold text-amber-700">MENUNGGU</span></div></div><div class="flex w-full gap-2 sm:w-auto"><select v-model="roleSel[u.id]" class="control"><option v-for="role in roles" :key="role" :value="role">{{ roleLabels[role] ?? role }}</option></select><button class="primary-button" @click="approve(u)">Setujui</button></div></div></div></section><section><div class="mb-3 flex items-center gap-2"><CheckCircle2 :size="18" class="text-emerald-500" /><h2 class="text-sm font-bold">Aktif ({{ activeUsers.length }})</h2></div><div class="space-y-3"><div v-for="u in activeUsers" :key="u.id" class="user-card"><div class="flex min-w-0 items-start gap-3"><UserRound :size="19" class="mt-1 text-slate-400" /><div><div class="font-bold">{{ u.name }}</div><div class="text-xs text-slate-500">{{ u.email }} · NIK: {{ u.nik }}</div><span class="mt-2 inline-flex rounded-full bg-emerald-100 px-2 py-1 text-[10px] font-bold text-emerald-700">{{ roleLabels[u.roles?.[0]?.name] ?? '—' }}</span></div></div><div class="flex w-full flex-wrap gap-2 sm:w-auto"><select v-model="roleSel[u.id]" class="control"><option v-for="role in roles" :key="role" :value="role">{{ roleLabels[role] ?? role }}</option></select><button class="secondary-button" @click="changeRole(u)">Ubah Role</button><button class="danger-button" @click="deactivate(u)"><XCircle :size="15" /> Nonaktifkan</button></div></div></div></section><div class="flex items-center justify-center gap-3 text-sm"><button v-if="users.current_page > 1" class="page-button" @click="router.get(route('users.index', { page: users.current_page - 1 }), {}, { preserveScroll: true, preserveState: true })">Sebelumnya</button><span class="text-slate-500">{{ users.from }}–{{ users.to }} dari {{ users.total }}</span><button v-if="users.current_page < users.last_page" class="page-button" @click="router.get(route('users.index', { page: users.current_page + 1 }), {}, { preserveScroll: true, preserveState: true })">Selanjutnya</button></div></div></template>
<style scoped>.user-card{display:flex;align-items:center;justify-content:space-between;gap:1rem;border:1px solid #e2e8f0;border-radius:.875rem;background:#fff;padding:1rem;flex-wrap:wrap}.user-card.pending{border-color:#fde68a;background:#fffbeb}.control{height:2.35rem;border:1px solid #cbd5e1;border-radius:.5rem;background:#fff;padding:0 .65rem;font-size:.75rem}.primary-button,.secondary-button,.danger-button,.page-button{display:inline-flex;align-items:center;justify-content:center;gap:.35rem;border-radius:.5rem;padding:.55rem .7rem;font-size:.75rem;font-weight:700}.primary-button{background:#f97316;color:#fff}.secondary-button,.page-button{border:1px solid #e2e8f0;background:#fff;color:#c2410c}.danger-button{background:#fef2f2;color:#dc2626}</style>
